<?php declare(strict_types=1); namespace Annam; $title='Create booking'; ?>
<form method="post" class="o-form"><?= csrf() ?><input type="hidden" name="token" value="<?= e($token) ?>"><section class="o-card"><h2>Customer & delivery</h2><div class="o-grid-form"><label class="o-field">Name<input name="name" value="<?= e($conversation['display_name']??'') ?>" required maxlength="120"></label><label class="o-field">Mobile number<input name="phone" type="tel" value="<?= e($conversation['phone']??'') ?>" required maxlength="20"></label><label class="o-field">Channel<select name="channel"><option value="manual">Manual booking</option><option value="whatsapp" <?= $conversation?'selected':'' ?>>WhatsApp booking</option></select></label><label class="o-field">Payment<select name="payment_method"><option value="manual">Manual payment</option><option value="cod">Cash on delivery</option></select></label><label class="o-field">Delivery area<select name="zone_id"><option value="">Collection at kitchen</option><?php foreach($zones as $zone): ?><option value="<?= e($zone['id']) ?>"><?= e($zone['pincode'].' · '.$zone['area_name']) ?> (<?= money($zone['delivery_fee']) ?>)</option><?php endforeach; ?></select></label><label class="o-field">Delivery address<textarea name="address" maxlength="2000"></textarea></label></div></section><section class="o-card"><h2>Choose items</h2><input id="booking-filter" placeholder="Search dishes & products" type="search"><div class="php-booking-items"><?php foreach($items as $item): if(!$item['active'])continue; ?><label class="php-booking-item"><span><?= e($item['name']) ?> <small><?= money($item['price']) ?></small></span><input type="number" name="quantities[<?= e($item['id']) ?>]" min="0" max="999" placeholder="0" aria-label="Quantity for <?= e($item['name']) ?>"></label><?php endforeach; ?></div></section><button class="o-btn o-btn-primary">Create unpaid booking</button></form><script src="/assets/workflow.js" defer></script>
